+// 统计降序序列 (偶数 lane 为 value) 中 >= x 的元素个数, 二分实现
+template <typename QLIV2T>
+__aicore__ inline int32_t QLIV2Vector<QLIV2T>::CountGE(const LocalTensor<float> &sortedDesc, int32_t n, float x)
+{
+    int32_t lo = 0;
+    int32_t hi = n;
+    while (lo < hi) {
+        int32_t mid = (lo + hi) / 2;
+        if (sortedDesc.GetValue(2 * mid) >= x) {
+            lo = mid + 1;
+        } else {
+            hi = mid;
+        }
+    }
+    return lo;
+}
