+    ge::DataType idxOffsetType = ge::DT_INT32;
+    std::string layoutQ = "BSND";
+    std::string layoutK = "PA_BBND";
+    int64_t topk = 2048;
+    int64_t quantMode = 2;
+    int64_t maxSeqlenQ = -1;
