+ge::graphStatus SMLAInfoParser::GetActualSeqLenQSize(uint32_t &size)
+{
+    return GetActualSeqLenSize(size, opParamInfo_.cuSeqLensQ.tensor, qLayout_, "cu_seqlens_q");
+}
