+// 将isCheckTiling设置为false, 输入输出的max&sum&exp的shape为(m, 1)
+constexpr SoftmaxConfig SMLA_SOFTMAX_FLASHV2_CFG_WITHOUT_BRC = {false, 0, 0, SoftmaxMode::SOFTMAX_OUTPUT_WITHOUT_BRC};
+
