+    uint32_t mSize = mSplitInfo.nBufferDealM;
+    uint32_t mL1Size = M_SPLIT_SIZE;
+    uint32_t mL1SizeAlign = SMLAAlign(M_SPLIT_SIZE, 16);
+    uint32_t mL1Loops = CeilDiv(mSize, M_SPLIT_SIZE);
