+                    fixParams.srcStride = mL1SizeAlign;
+                    fixParams.dstStride = nSize; // mm2ResGm两行之间的间隔
+                    fixParams.ndNum = 1;         // 输出ND
+                    fixParams.unitFlag = 0b11;
