+            flag1_bmm2_ = 1;
+            return a_;
+        } else if (flag1_bmm2_ == 1) {
+            flag1_bmm2_ = NUM_2;
+            return b_;
+        } else {
+            flag1_bmm2_ = 0;
+            return c_;
+        }
+    }
+
