+TEMPLATES_DEF_NO_DEFAULT
+__aicore__ inline void CSABlockCube<TEMPLATE_ARGS>::IterateBmm2(StaticBuffer<T> &outputBuf,
+                                                                StaticBuffer<Q_T> &l1PBuffer, const RunInfo &runInfo,
+                                                                const ConstInfo &constInfo)
