+template <typename T1, typename T2>
+__aicore__ inline T1 SMLAAlign(T1 num, T2 rnd)
+{
+    return (rnd == 0) ? 0 : ((num + rnd - 1) / rnd * rnd);
+}
+
+template <typename T1, typename T2>
+__aicore__ inline T1 CeilDiv(T1 num, T2 rnd)
