+    // FP32的0值和极大值
+    static constexpr float FLOAT_ZERO = 0;
+    static constexpr float FLOAT_MAX = 3.402823466e+38F;
+
+    // preLoad的总次数
+    uint32_t preLoadNum = 0U;
+    uint32_t nBufferMBaseSize = 0U;
+    // CUBE和VEC的核间同步EventID
+    uint32_t syncV0C1 = 0U;
