+    uint32_t mmResUbSize = 0U;   // Matmul1输出结果GM上的大小
+    uint32_t vec1ResUbSize = 0U; // Vector1输出结果GM上的大小
+    uint32_t bmm2ResUbSize = 0U; // Matmul2输出结果GM上的大小
+    uint64_t batchSize = 0ULL;
