+    uint64_t headDim = 0;
+    uint64_t kvSeqSize = 0ULL;    // kv最大S长度
+    uint64_t qSeqSize = 1ULL;     // q最大S长度
+    int64_t kvCacheBlockSize = 0; // PA场景的block size
+    uint64_t paCmpBlockSize = 0;
+    uint64_t paOriBlockSize = 0;
