+struct ScopeGuard {
+    explicit ScopeGuard(std::function<void()> onExitScope)
+        : m_exitFunc(std::move(onExitScope)),
+          m_isDismissed(false)
+    {}
+    // 禁止拷贝
+    ScopeGuard(const ScopeGuard &) = delete;
+    ScopeGuard &operator=(const ScopeGuard &) = delete;
+
+    ~ScopeGuard()
+    {
+        if (!m_isDismissed) {
+            m_exitFunc();
+        }
+    }
+
+    void Dismiss()
+    {
+        m_isDismissed = true;
+    }
+
+    std::function<void()> m_exitFunc;
+    bool m_isDismissed;
+};
