+std::string TopkLengthShapeToStringSmla(const aclTensor *topkLengthOptional)
+{
+    const auto &shape = topkLengthOptional->GetViewShape();
+    std::string result;
+    for (size_t i = 0; i < shape.GetDimNum(); ++i) {
+        if (i != 0) {
+            result += ", ";
+        }
+        result += std::to_string(shape.GetDim(i));
+    }
+    return result;
+}
