+struct TopkLengthAxisSmla {
+    int64_t index;
+    const char *desc;
+};
+
+inline constexpr TopkLengthAxisSmla SMLA_TOPK_LENGTH_SECOND_AXIS{1, "second"};
+inline constexpr TopkLengthAxisSmla SMLA_TOPK_LENGTH_THIRD_AXIS{2, "third"};
