+                    OP_LOGE_FOR_INVALID_SHAPEDIM_WITH_REASON(SMLA_ACLNN_OP_NAME, "ori_topk_length",
+                                                             std::to_string(dimNum),
+                                                             "The shape dim of ori_topk_length must be 3 "
+                                                             "when layout_q is BSND");
