+/*!
+ * \file sparse_flash_mla_metadata_aicpu.cpp
+ * \brief
+ */
+
+#include "log.h"
+#include "status.h"
+#include <cstdio>
+#include <cmath>
+#include "sparse_flash_mla_metadata_aicpu.h"
+
+using namespace optiling;
